def write_json(name, value):
    with (EVIDENCE / name).open('x', encoding='utf-8') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def git(*args):
    return subprocess.check_output(['git', *args], cwd=TARGET, text=True)


def changed():
    values = git('diff', '--name-only', '-z', 'HEAD').split('\0')
    values += git('ls-files', '--others', '--exclude-standard', '-z').split('\0')
    return sorted(set(filter(None, values)))


def inventory():
    paths = git('ls-files', '-z', '--', 'm3/collections').split('\0')
    paths += git('ls-files', '--others', '--exclude-standard', '-z', '--', 'm3/collections').split('\0')
    return {relative: {'sha256': sha(helper.contained(TARGET, relative)),
                       'mode': oct((TARGET / relative).stat().st_mode & 0o7777)}
            for relative in sorted(set(filter(None, paths)))}


def verify_state(count):
    if git('rev-parse', 'HEAD').strip() != REVISION:
        raise ValueError('target revision drift')
    if subprocess.run(['git', 'symbolic-ref', '-q', 'HEAD'], cwd=TARGET,
                      stdout=subprocess.PIPE, stderr=subprocess.PIPE).returncode != 1:
        raise ValueError('target must remain detached')
    expected = sorted(row[1] for row in PASSES[:count])
    if changed() != expected:
        raise ValueError('target changes exceed the serial admitted scope: ' + repr(changed()))
    for index, row in enumerate(PASSES):
        path = helper.contained(TARGET, row[1])
        actual = sha(path) if path.exists() else 'ABSENT'
        if actual != row[3 if index < count else 2]:
            raise ValueError('target pre/post drift: ' + row[1])


def qualified(row):
    name, relative, before, after, result_sha, inputs_sha, report_sha, patch_sha, count = row
    candidate = HOST / 'target/candidate' / name
    report = HOST / 'target' / name / 'surefire-reports/TEST-com.synexia.rewrite.M3TaskRecipeTest.xml'
    files = {'SDK_RESULTS.tsv': (candidate / 'SDK_RESULTS.tsv', result_sha),
             'SDK_INPUTS.tsv': (candidate / 'SDK_INPUTS.tsv', inputs_sha),
             'SDK_REPORT.xml': (report, report_sha),
             'java.patch': (candidate / 'java.patch', patch_sha)}
    for label, (path, expected) in files.items():
        if sha(path) != expected:
            raise ValueError('qualified evidence drift: ' + name + '/' + label)
    suite = ET.parse(report).getroot()
    if (int(suite.attrib['tests']) != len(helper.TESTS)
            or any(int(suite.attrib[key]) for key in ('errors', 'failures', 'skipped'))
            or {item.attrib['name'] for item in suite.findall('testcase')} != helper.TESTS):
        raise ValueError('all five actual SDK tests must pass: ' + name)
    props = {p.attrib['name']: p.attrib.get('value', '') for p in suite.findall('./properties/property')}
    expected_props = {'m3.pass': name, 'm3.crate.name': 'm3-wrapper-' + name,
                      'm3.recipe.name': 'com.synexia.m3.WrapperConvergence20261018'}
    for key, value in expected_props.items():
        if props.get(key) != value:
            raise ValueError('SDK identity mismatch: ' + key)
    for key, value in {'m3.crate.root': HOST, 'm3.recipe.owner.root': OWNER,
                       'm3.candidate.root': candidate}.items():
        if Path(props[key]).resolve() != value.resolve():
            raise ValueError('SDK path mismatch: ' + key)
    expected_paths = {'host/' + p: HOST / p for p in
                      ('pom.xml', 'README.md', 'ENGINE_SOURCES.tsv', 'HARNESS_LINEAGE.json')}
    for directory in (HOST / 'src', HOST / 'passes' / name):
        for path in directory.rglob('*'):
            if path.is_file():
                key = 'host/' + path.relative_to(HOST).as_posix()
                expected_paths[key] = helper.contained(HOST, key.removeprefix('host/'))
    expected_paths['contract/CONTRACT.md'] = helper.contained(CRATE, 'CONTRACT.md')
    for engine in helper.OWNERS:
        path = 'src/main/java/com/synexia/rewrite/' + engine
        expected_paths['owner/' + path] = helper.contained(OWNER, path)
    cp = props.get('m3.parser.classpath', '').split(os.pathsep)
    for index, text in enumerate(cp):
        if not text:
            raise ValueError('empty parser classpath')
        entry = Path(text)
        if not entry.exists() or entry.is_symlink():
            raise ValueError('missing or symlink parser classpath')
        for path in sorted(entry.rglob('*')) if entry.is_dir() else [entry]:
            if path.is_file():
                suffix = path.relative_to(entry).as_posix() if entry.is_dir() else entry.name
                expected_paths[f'parser-classpath/{index}/{suffix}'] = (
                    helper.contained(entry, suffix) if entry.is_dir() else entry)
    bound = dict(helper.rows(candidate / 'SDK_INPUTS.tsv', 2))
    if set(bound) != set(expected_paths) or len(bound) != count:
        raise ValueError('incomplete or extra SDK binding: ' + name)
    for key, path in expected_paths.items():
        if sha(path) != bound[key]:
            raise ValueError('SDK input changed after qualification: ' + key)
    engines = helper.rows(HOST / 'ENGINE_SOURCES.tsv', 5)
    if {Path(row[0]).name for row in engines} != set(helper.OWNERS):
        raise ValueError('canonical engine closure mismatch')
    for source, blob, digest, license_id, url in engines:
        path = helper.contained(OWNER, source.removeprefix('synexia-openrewrite-recipes/'))
        data = path.read_bytes()
        actual_blob = hashlib.sha1(b'blob ' + str(len(data)).encode('ascii') + b'\0' + data).hexdigest()
        if sha(path) != digest or actual_blob != blob or license_id != 'Apache-2.0':
            raise ValueError('canonical engine custody changed: ' + source)
    lane = HOST / 'passes' / name / 'resources/com/synexia/rewrite/hash-pinned-java' / ('m3-wrapper-' + name)
    manifest = helper.rows(lane / 'manifest.tsv', 4)
    if len(manifest) != 1 or manifest[0][:3] != [relative, before, after]:
        raise ValueError('manifest target mismatch')
    if sha(helper.contained(lane, manifest[0][3])) != after:
        raise ValueError('manifest template changed')
    if before != 'ABSENT' and sha(helper.contained(lane, 'pre/' + manifest[0][3])) != before:
        raise ValueError('manifest preimage changed')
    if helper.rows(candidate / 'SDK_RESULTS.tsv', 3) != [[relative, before, after]]:
        raise ValueError('actual SDK result mismatch')
    if sha(helper.contained(candidate, relative)) != after:
        raise ValueError('actual SDK output changed')
    refusals = helper.rows(candidate / 'SDK_REFUSALS.tsv', 3)
    expected_refusals = {'duplicate-source', 'post-scan-drift', 'source-drift', 'wrong-java-representation'}
    if before != 'ABSENT':
        expected_refusals.add('missing-source')
    if {cells[0] for cells in refusals} != expected_refusals:
        raise ValueError('incomplete SDK refusal evidence')
    for case, digest, diagnostic in refusals:
        decoded = diagnostic.replace('\\t', '\t').replace('\\r', '\r').replace('\\n', '\n')
        if helper.digest(decoded.encode('utf-8')) != digest:
            raise ValueError('refusal diagnostic changed: ' + case)
    patch = candidate / 'java.patch'
    numstat = git('apply', '--numstat', str(patch)).splitlines()
    if len(numstat) != 1 or numstat[0].split('\t')[-1] != relative:
        raise ValueError('SDK patch target mismatch')
    return {'pass': name, 'target': relative, 'before': before, 'after': after,
            'sdk_patch': str(patch), 'verified_bound_inputs': len(bound),
            'sdk_inputs_unchanged': True, 'sdk_tests': sorted(helper.TESTS),
            'sdk_refusals': sorted(expected_refusals), 'parser_classpath': cp,
            'evidence_sha256': {label: expected for label, (path, expected) in files.items()},
            'sdk_refusals_sha256': sha(candidate / 'SDK_REFUSALS.tsv'),
            'helper_source': HELPER_RELATIVE, 'helper_sha256': HELPER_SHA}


def command(name, argv):
    metadata = {'argv': argv, 'cwd': str(TARGET), 'utc': datetime.now(timezone.utc).isoformat()}
    write_json(name + '.command.json', metadata)
    start = time.monotonic()
    with (EVIDENCE / (name + '.stdout.log')).open('xb') as stdout, \
            (EVIDENCE / (name + '.stderr.log')).open('xb') as stderr:
        result = subprocess.run(argv, cwd=TARGET, stdout=stdout, stderr=stderr)
    metadata.update({'exit': result.returncode, 'elapsed_seconds': time.monotonic() - start,
                     'status': 'PASS' if result.returncode == 0 else 'FAIL'})
    write_json(name + '.receipt.json', metadata)
    if result.returncode:
        raise ValueError('command failed: ' + name)
    return metadata


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['admit'] + [row[0] for row in PASSES])
    args = parser.parse_args()
    if args.action == 'admit':
        verify_state(0)
        results = [qualified(row) for row in PASSES]
        write_json('02-admission.json', {'status': 'PASS', 'revision': REVISION,
                   'actual_sdk_results': True, 'passes': results,
                   'initial_source_state': inventory(), 'utc': datetime.now(timezone.utc).isoformat()})
        print('PASS admission: all three preconditions and 999 pass-bound inputs verified')
        return
    index = next(i for i, row in enumerate(PASSES) if row[0] == args.action)
    admission = json.loads((EVIDENCE / '02-admission.json').read_text())
    verify_state(index)
    current = inventory()
    allowed = {row[1] for row in PASSES[:index]}
    if {p: h for p, h in current.items() if p not in allowed} != {
            p: h for p, h in admission['initial_source_state'].items() if p not in allowed}:
        raise ValueError('unrelated owning-module input drift')
    if index and not (EVIDENCE / (f'{index + 2:02d}-' + PASSES[index - 1][0] + '.json')).exists():
        raise ValueError('prior serial receipt missing')
    row = PASSES[index]
    result = qualified(row)
    prefix = f'{index + 3:02d}-' + row[0]
    result['commands'] = [command(prefix + '-check', ['git', 'apply', '--check', result['sdk_patch']]),
                          command(prefix + '-apply', ['git', 'apply', result['sdk_patch']])]
    verify_state(index + 1)
    after = inventory()
    if sorted(p for p in set(current) | set(after) if current.get(p) != after.get(p)) != [row[1]]:
        raise ValueError('SDK pass changed an unrelated owning-module input')
    result.update({'status': 'PASS', 'changed_files': [row[1]], 'actual_sdk_results': True,
                   'utc': datetime.now(timezone.utc).isoformat()})
    write_json(prefix + '-source-state.json', after)
    write_json(prefix + '.json', result)
    print('PASS actual SDK reception:', row[0], row[3])


if __name__ == '__main__':
    main()
